from PIL import Image
im = Image.open('tmp/ui-acceptance/calendar/r102-seg-light.png').convert('RGB')
px = im.load()
def rle(y,x0,x1):
    vals=[px[x,y][0] for x in range(x0,x1)]
    out=[];s=0;cur=vals[0]
    for i,v in enumerate(vals[1:],1):
        if v!=cur: out.append(f"{cur}@{x0+s}"+(f"-{x0+i-1}" if i-1>s else "")); s=i;cur=v
    out.append(f"{cur}@{x0+s}-{x1-1}")
    return " ".join(out)
for y in (37,40,44,48,52,56,60,62):
    print(f"y={y:2d}:", rle(y,555,765))
def runs(y0,y1,x0,x1,thr=128):
    out=[];s=None
    for x in range(x0,x1):
        n=sum(1 for y in range(y0,y1) if px[x,y][0]<thr)
        if n>0 and s is None: s=x
        elif n==0 and s is not None: out.append((s,x-1)); s=None
    if s is not None: out.append((s,x1-1))
    return out
print("ink runs:", runs(40,60,555,765))
